// Package platform serves the Platform API (/platform/v1): partners, tenants,
// their environments and host names, tenant lifecycle and export, and the
// operations of long-running requests (ADR-0009, ADR-0018).
//
// The server code is generated by ogen from api/openapi/platform/openapi.yaml
// (package platformgen); this package implements its Handler on top of the
// tenancy module's facade and wires the shared middleware of package apimw:
//
//	request
//	  -> bearer authentication (B0 bootstrap operator token, 401)
//	  -> Idempotency-Key replay of POST requests
//	  -> generated router: parameters and body validated (400/412/422)
//	  -> authorization of x-required-permission (403), Change-Reason and
//	     Change-Ticket into the request scope (422), route label
//	  -> handler
//
// Every error, including unknown paths and methods, is an RFC 9457 problem.
// Tenants carry their version as a strong ETag ("3"); changes require it in
// If-Match, and a missing, malformed or stale value is a 412
// precondition_failed (the platform has no 428 error code).
//
// Mount the handler returned by New on Prefix of an httpx.Router.
package platform

import (
	"net/http"

	"github.com/antonyrejith/portun/api/openapi"
	"github.com/antonyrejith/portun/internal/api/apimw"
	"github.com/antonyrejith/portun/internal/api/platformgen"
	"github.com/antonyrejith/portun/internal/modules/tenancy"
	"github.com/antonyrejith/portun/internal/platform/errs"
	"github.com/antonyrejith/portun/internal/platform/httpx"
	"github.com/antonyrejith/portun/internal/platform/idempotency"
)

// Prefix is the path prefix of the Platform API. Mount the handler with
// Router.Handle(Prefix, h).
const Prefix = "/platform/v1/"

// Deps are the dependencies of the Platform API. All are required except
// Authorizer.
type Deps struct {
	// Tenancy is the tenancy module.
	Tenancy *tenancy.Module
	// Auth configures the bootstrap operator token (B0).
	Auth apimw.AuthConfig
	// Authorizer decides permissions; apimw.OperatorAuthorizer when nil.
	Authorizer apimw.Authorizer
	// Idempotency stores the results of POST requests.
	Idempotency *idempotency.Store
}

// New returns the Platform API handler. It fails when a dependency is
// missing, the operation table cannot be built from the embedded
// specification (an operation lacks x-required-permission or x-audit-event),
// or the generated server cannot be created.
func New(d Deps) (http.Handler, error) {
	if d.Tenancy == nil {
		return nil, errs.New(errs.CodeInternal, "platform api: Tenancy is required")
	}
	if d.Idempotency == nil {
		return nil, errs.New(errs.CodeInternal, "platform api: Idempotency is required")
	}
	ops, err := apimw.ParseOperations(openapi.Platform)
	if err != nil {
		return nil, err //nolint:wrapcheck // already an *errs.Error
	}
	auth, err := apimw.NewAuthenticator(d.Auth)
	if err != nil {
		return nil, err //nolint:wrapcheck // already an *errs.Error
	}
	authz := d.Authorizer
	if authz == nil {
		authz = apimw.OperatorAuthorizer{}
	}
	srv, err := platformgen.NewServer(&handler{tenancy: d.Tenancy}, security{},
		platformgen.WithErrorHandler(apimw.ErrorHandler(ops)),
		platformgen.WithNotFound(apimw.NotFound),
		platformgen.WithMethodNotAllowed(apimw.MethodNotAllowed),
		platformgen.WithMiddleware(apimw.Middleware(ops, authz)),
	)
	if err != nil {
		return nil, errs.Wrap(errs.CodeInternal, err, "platform api: create the generated server")
	}
	return httpx.Chain(http.Handler(srv),
		auth.Middleware(),
		d.Idempotency.Middleware(idempotency.PlatformScope),
	), nil
}
